import React from 'react';
import { useAudit } from '../../hooks/useAudit';
import StatusBadge from '../shared/StatusBadge';
import LoadingState from '../shared/LoadingState';

export default function ControlAuditList({ machineId }) {
  const { entries, loading } = useAudit(machineId);

  if (loading) return <LoadingState message="Loading audit..." />;

  if (entries.length === 0) {
    return (
      <div style={{
        padding:        '20px',
        textAlign:      'center',
        fontFamily:     "'Share Tech Mono', monospace",
        fontSize:       '11px',
        color:          'var(--text-muted)',
        border:         '1px dashed rgba(0,212,255,0.12)',
        borderRadius:   '8px',
        letterSpacing:  '0.08em',
      }}>
        NO AUDIT ENTRIES
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
      {entries.slice(0, 10).map((entry, i) => (
        <div
          key={i}
          style={{
            display:       'grid',
            gridTemplateColumns: '1fr auto auto',
            alignItems:    'center',
            gap:           '10px',
            padding:       '8px 10px',
            background:    'rgba(0, 12, 32, 0.65)',
            border:        '1px solid rgba(0,212,255,0.07)',
            borderRadius:  '6px',
            fontFamily:    "'Share Tech Mono', monospace",
            fontSize:      '11px',
            animation:     'fade-up 300ms ease both',
            animationDelay: `${i * 30}ms`,
          }}
        >
          <div style={{ minWidth: 0 }}>
            <span style={{ color: 'var(--cyan)', textTransform: 'uppercase' }}>
              {entry.command}
            </span>
            {entry.value !== undefined && entry.value !== null && (
              <span style={{ color: 'var(--text-muted)', marginLeft: '6px' }}>
                → {entry.value}
              </span>
            )}
            {entry.actor && (
              <div style={{ color: 'var(--text-muted)', fontSize: '9px', marginTop: '2px' }}>
                {entry.actor}
              </div>
            )}
          </div>

          <StatusBadge status={entry.status} size="sm" />

          <span style={{ color: 'var(--text-muted)', fontSize: '10px', whiteSpace: 'nowrap' }}>
            {entry.requested_at
              ? new Date(entry.requested_at).toLocaleTimeString('en-US', { hour12: false })
              : '—'}
          </span>
        </div>
      ))}
    </div>
  );
}
