import { useState, useCallback, useRef } from 'react';
import { postCommand, pollCommand } from '../api/gateway';

const MAX_POLLS = 20;
const POLL_INTERVAL = 1000;

export function useCommand() {
  const [status, setStatus] = useState(null); // null | 'pending' | 'applied' | 'rejected' | 'error'
  const [commandId, setCommandId] = useState(null);
  const [error, setError] = useState(null);
  const [result, setResult] = useState(null);
  const pollRef = useRef(null);
  const simTimeoutRef = useRef(null);

  const clearPoll = () => {
    if (pollRef.current) {
      clearInterval(pollRef.current);
      pollRef.current = null;
    }
    if (simTimeoutRef.current) {
      clearTimeout(simTimeoutRef.current);
      simTimeoutRef.current = null;
    }
  };

  const dispatchAuditEntry = (machineId, command, value, reason, cmdStatus) => {
    try {
      window.dispatchEvent(
        new CustomEvent('scada-command-applied', {
          detail: {
            machineId,
            command,
            value,
            reason,
            actor: 'operator (sim)',
            requested_at: new Date().toISOString(),
            status: cmdStatus,
          },
        })
      );
    } catch (_) {}
  };

  const submit = useCallback(async (machineId, command, value, reason) => {
    clearPoll();
    setStatus('pending');
    setError(null);
    setResult(null);

    try {
      const res = await postCommand(machineId, { command, value, reason });
      const id = res.command_id;
      setCommandId(id);

      let polls = 0;
      pollRef.current = setInterval(async () => {
        polls++;
        try {
          const cmdResult = await pollCommand(id);
          if (cmdResult.status !== 'pending') {
            clearPoll();
            setStatus(cmdResult.status);
            setResult(cmdResult);
            if (cmdResult.status === 'applied') {
              dispatchAuditEntry(machineId, command, value, reason, 'applied');
            }
            return;
          }
        } catch (_) {
          // ignore transient fetch errors during polling
        }
        if (polls >= MAX_POLLS) {
          clearPoll();
          setStatus('error');
          setError('Command timed out waiting for confirmation.');
        }
      }, POLL_INTERVAL);
    } catch (err) {
      // Gateway offline — simulate command lifecycle in demo mode
      simTimeoutRef.current = setTimeout(() => {
        setStatus('applied');
        setResult({ status: 'applied', applied_at: new Date().toISOString() });
        dispatchAuditEntry(machineId, command, value, reason, 'applied');
      }, 900);
    }
  }, []);

  const reset = useCallback(() => {
    clearPoll();
    setStatus(null);
    setCommandId(null);
    setError(null);
    setResult(null);
  }, []);

  return { submit, reset, status, commandId, error, result };
}
