import React from 'react';
import StatusBadge from '../shared/StatusBadge';

function HealthGauge({ value, color }) {
  const r            = 38;
  const cx           = 48;
  const cy           = 48;
  const fullCirc     = 2 * Math.PI * r;
  // Only 270° of the arc is used (start at 135° from top = 7 o'clock, end at 45° = 5 o'clock)
  const arcLength    = fullCirc * 0.75;
  const filled       = arcLength * (Math.max(0, Math.min(100, value)) / 100);

  return (
    <svg width="96" height="96" viewBox="0 0 96 96" style={{ overflow: 'visible' }}>
      {/* Track */}
      <circle
        cx={cx} cy={cy} r={r}
        fill="none"
        stroke="rgba(0,212,255,0.08)"
        strokeWidth="7"
        strokeDasharray={`${arcLength} ${fullCirc}`}
        strokeDashoffset={-fullCirc * 0.125}   /* rotate start to 7-o'clock */
        strokeLinecap="round"
      />
      {/* Value arc */}
      <circle
        cx={cx} cy={cy} r={r}
        fill="none"
        stroke={color}
        strokeWidth="7"
        strokeDasharray={`${filled} ${fullCirc - filled}`}
        strokeDashoffset={-fullCirc * 0.125}
        strokeLinecap="round"
        style={{
          filter:     `drop-shadow(0 0 5px ${color})`,
          transition: 'stroke-dasharray 700ms ease',
        }}
      />
      {/* Label */}
      <text x={cx} y={cy - 3} textAnchor="middle" dominantBaseline="middle"
        style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: '19px', fill: color, fontWeight: 'bold' }}>
        {value}
      </text>
      <text x={cx} y={cy + 14} textAnchor="middle"
        style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: '9px', fill: 'rgba(120,168,204,0.8)', letterSpacing: '0.04em' }}>
        HEALTH
      </text>
    </svg>
  );
}

export default function MachineHealth({ machineId, telemetry, isOffline }) {
  const dataKey = machineId === 'refinery-1' ? 'refinery_1' : 'refinery_2';
  const data    = telemetry?.[dataKey] || {};

  let health = 100;
  if (isOffline)                     health = 0;
  else if (data.status === 'offline') health = 0;
  else if (data.status === 'critical') health = 20;
  else if (data.status === 'error')   health = 60;
  else if (data.status === 'warning') health = 70;

  // Regular: Cyan (#00d4ff), Abnormal: Yellow (#ffd700), Severe: Red (#ff3366)
  const color  = health >= 80 ? '#00d4ff' : health >= 50 ? '#ffd700' : '#ff3366';
  const status = isOffline ? 'offline' : (data.status || 'online');

  return (
    <div style={{
      display:    'flex',
      alignItems: 'center',
      gap:        '20px',
      padding:    '14px 16px',
      background: 'rgba(0, 15, 40, 0.6)',
      border:     '1px solid rgba(0,212,255,0.1)',
      borderRadius: '10px',
    }}>
      <HealthGauge value={health} color={color} />

      <div style={{ display: 'flex', flexDirection: 'column', gap: '9px', flex: 1 }}>
        <StatusBadge status={status} />

        <div style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: '11px', color: 'var(--text-muted)', lineHeight: 1.7 }}>
          <div>ID: <span style={{ color: 'var(--text-secondary)' }}>{machineId}</span></div>
          {data.last_update && (
            <div>
              LAST UPDATE:{' '}
              <span style={{ color: 'var(--cyan)' }}>
                {new Date(data.last_update).toLocaleTimeString()}
              </span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
