import React from 'react';

export default function AlarmBeacon({ active, severity = 'warning' }) {
  if (!active) return null;
  const isSevere = severity === 'critical' || severity === 'severe' || severity === 'danger';
  const color = isSevere ? 'var(--danger)' : 'var(--amber)';

  return (
    <div style={{
      position: 'absolute',
      top:      '-9px',
      right:    '-9px',
      width:    '20px',
      height:   '20px',
      zIndex:   10,
      pointerEvents: 'none',
    }}>
      {/* Expanding ring */}
      <div style={{
        position:     'absolute',
        inset:        0,
        borderRadius: '50%',
        background:   color,
        animation:    'pulse-ring 1.5s ease-out infinite',
        opacity:      0.7,
      }} />
      {/* Solid dot */}
      <div style={{
        position:     'absolute',
        inset:        '4px',
        borderRadius: '50%',
        background:   color,
        boxShadow:    `0 0 8px ${color}`,
        animation:    'danger-pulse 1.5s ease-in-out infinite',
      }} />
    </div>
  );
}
