import { useState, useEffect, useRef, useCallback } from 'react';
import { fetchAllModbus, fetchHealth } from '../api/gateway';

const POLL_INTERVAL = 2000;

/* ── Demo / simulation data ──────────────────────────────────────────────── */
// Generates realistic fake telemetry so the UI looks alive when the gateway
// is not running. Values drift slowly with small random noise.
let _simTemp     = 342;
let _simPressure = 4.2;
let _simFlow     = 127;

function getSimData() {
  _simTemp     = Math.max(280, Math.min(480, _simTemp     + (Math.random() - 0.5) * 3));
  _simPressure = Math.max(2.5, Math.min(8.0, _simPressure + (Math.random() - 0.5) * 0.1));
  _simFlow     = Math.max( 80, Math.min(260, _simFlow     + (Math.random() - 0.5) * 4));

  return {
    refinery_1: {
      temperature:  parseFloat(_simTemp.toFixed(1)),
      pressure:     parseFloat(_simPressure.toFixed(2)),
      last_update:  new Date().toISOString(),
      status:       'online',
    },
    refinery_2: {
      flow_rate:    parseFloat(_simFlow.toFixed(1)),
      last_update:  new Date().toISOString(),
      status:       'online',
    },
  };
}

const SIM_HEALTH = {
  status:  'online',
  service: 'scada_gateway (DEMO)',
  plc_1:   'connected',
  plc_2:   'connected',
};

/* ── Hook ────────────────────────────────────────────────────────────────── */
export function useTelemetry() {
  const [data,        setData]        = useState(() => getSimData());
  const [health,      setHealth]      = useState(SIM_HEALTH);
  const [lastUpdated, setLastUpdated] = useState(() => new Date());
  const [isOffline,   setIsOffline]   = useState(false);
  const [isDemoMode,  setIsDemoMode]  = useState(true);
  const [error,       setError]       = useState(null);
  const timerRef      = useRef(null);
  const failCountRef  = useRef(0);

  const poll = useCallback(async () => {
    try {
      const [modbusData, healthData] = await Promise.all([
        fetchAllModbus(),
        fetchHealth(),
      ]);
      failCountRef.current = 0;
      setData(modbusData);
      setHealth(healthData);
      setLastUpdated(new Date());
      setIsOffline(false);
      setIsDemoMode(false);
      setError(null);
    } catch (err) {
      failCountRef.current += 1;
      setError(err.message);

      if (failCountRef.current >= 2) {
        // Gateway not reachable — fall back to demo simulation
        setIsOffline(false);   // not "offline" in the UI — we have demo data
        setIsDemoMode(true);
        setData(getSimData());
        setHealth(SIM_HEALTH);
        setLastUpdated(new Date());
      }
    }
  }, []);

  useEffect(() => {
    poll();

    const startPolling = () => {
      if (!timerRef.current) {
        timerRef.current = setInterval(poll, POLL_INTERVAL);
      }
    };
    const stopPolling = () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    };
    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopPolling();
      } else {
        poll();
        startPolling();
      }
    };

    startPolling();
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      stopPolling();
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [poll]);

  return { data, health, lastUpdated, isOffline, isDemoMode, error };
}
