import React from 'react';
import { AlertTriangle } from 'lucide-react';

const SEVERITY_COLORS = {
  critical: '#ff3366',
  severe:   '#ff3366',
  high:     '#ffd700',
  medium:   '#ffd700',
  low:      '#ffd700',
  warning:  '#ffd700',
  info:     '#00d4ff',
};

export default function AlarmRail({ alarms, onAcknowledge }) {
  const active = (alarms || []).filter(a => a.status !== 'acknowledged');
  if (active.length === 0) return null;

  const hasSevere = active.some(a => a.severity === 'critical' || a.severity === 'severe');
  const railColor = hasSevere ? '#ff3366' : '#ffd700';

  // Duplicate entries so the ticker loops seamlessly
  const items = active.length > 2 ? [...active, ...active] : active;

  return (
    <div style={{
      display:      'flex',
      alignItems:   'center',
      height:       '30px',
      background:   hasSevere ? 'rgba(255, 51, 102, 0.06)' : 'rgba(255, 215, 0, 0.06)',
      borderBottom: `1px solid ${hasSevere ? 'rgba(255, 51, 102, 0.25)' : 'rgba(255, 215, 0, 0.25)'}`,
      overflow:     'hidden',
      flexShrink:   0,
      position:     'relative',
    }}>
      {/* Label pill */}
      <div style={{
        flexShrink:    0,
        display:       'flex',
        alignItems:    'center',
        gap:           '5px',
        padding:       '0 12px',
        height:        '100%',
        borderRight:   `1px solid ${hasSevere ? 'rgba(255,51,102,0.3)' : 'rgba(255,215,0,0.3)'}`,
        fontFamily:    "'Share Tech Mono', monospace",
        fontSize:      '10px',
        letterSpacing: '0.12em',
        color:         railColor,
        background:    hasSevere ? 'rgba(255,51,102,0.1)' : 'rgba(255,215,0,0.1)',
      }}>
        <AlertTriangle size={10} />
        ALARMS
      </div>

      {/* Scrolling ticker */}
      <div style={{ flex: 1, overflow: 'hidden', position: 'relative' }}>
        <div style={{
          display:     'inline-flex',
          gap:         '32px',
          padding:     '0 20px',
          whiteSpace:  'nowrap',
          animation:   active.length > 2 ? 'ticker-scroll 22s linear infinite' : 'none',
        }}>
          {items.map((alarm, i) => {
            const col = SEVERITY_COLORS[alarm.severity] || '#ffd700';
            return (
              <span key={`${alarm.id}-${i}`} style={{
                display:    'inline-flex',
                alignItems: 'center',
                gap:        '7px',
                fontFamily: "'Share Tech Mono', monospace",
                fontSize:   '11px',
              }}>
                <span style={{
                  width: '6px', height: '6px',
                  borderRadius: '50%',
                  background: col,
                  boxShadow: `0 0 5px ${col}`,
                  flexShrink: 0,
                }} />
                <span style={{ color: col }}>
                  {(alarm.machine_id || 'SYSTEM').toUpperCase()}
                </span>
                <span style={{ color: 'var(--text-muted)' }}>—</span>
                <span style={{ color: 'var(--text-secondary)' }}>{alarm.message}</span>
                {onAcknowledge && i < active.length && (
                  <button
                    onClick={() => onAcknowledge(alarm.id)}
                    style={{
                      background:    'transparent',
                      border:        '1px solid rgba(255,51,102,0.3)',
                      borderRadius:  '3px',
                      color:         'rgba(255,51,102,0.7)',
                      fontSize:      '9px',
                      padding:       '1px 5px',
                      cursor:        'pointer',
                      fontFamily:    "'Share Tech Mono', monospace",
                      letterSpacing: '0.05em',
                    }}
                  >
                    ACK
                  </button>
                )}
              </span>
            );
          })}
        </div>
      </div>
    </div>
  );
}
