import React from 'react';
import { Play, RotateCcw, Zap, RefreshCw } from 'lucide-react';

const ICON_MAP = {
  purge: Zap,
  reset: RotateCcw,
  calibrate: RefreshCw,
  default: Play,
};

export default function ActionTriggerControl({
  id,
  label,
  description,
  icon = 'default',
  disabled,
  onTrigger,
  color = 'var(--cyan)',
}) {
  const IconComponent = ICON_MAP[icon] || ICON_MAP.default;

  return (
    <div style={{
      display:        'flex',
      alignItems:     'center',
      justifyContent: 'space-between',
      gap:            '12px',
      padding:        '10px 12px',
      background:     'rgba(0, 12, 32, 0.55)',
      border:         '1px solid rgba(0, 212, 255, 0.08)',
      borderRadius:   '8px',
    }}>
      <div style={{ flex: 1 }}>
        <div style={{
          fontFamily:    "'Share Tech Mono', monospace",
          fontSize:      '12px',
          color:         'var(--text-secondary)',
          letterSpacing: '0.06em',
          textTransform: 'uppercase',
          marginBottom:  '2px',
        }}>
          {label}
        </div>
        {description && (
          <div style={{
            fontFamily: "'Share Tech Mono', monospace",
            fontSize:   '10px',
            color:      'var(--text-muted)',
          }}>
            {description}
          </div>
        )}
      </div>

      <button
        type="button"
        disabled={disabled}
        onClick={() => !disabled && onTrigger && onTrigger(id, 1, `Triggered ${label}`)}
        style={{
          display:        'inline-flex',
          alignItems:     'center',
          gap:            '6px',
          padding:        '7px 12px',
          background:     'rgba(0, 212, 255, 0.09)',
          border:         `1px solid ${color}44`,
          borderRadius:   '6px',
          color:          color,
          fontFamily:     "'Share Tech Mono', monospace",
          fontSize:       '11px',
          letterSpacing:  '0.06em',
          cursor:         disabled ? 'not-allowed' : 'pointer',
          transition:     'all 200ms ease',
          opacity:        disabled ? 0.4 : 1,
          outline:        'none',
          boxShadow:      `0 0 8px ${color}1a`,
        }}
        onMouseEnter={e => {
          if (!disabled) {
            e.currentTarget.style.background = `${color}25`;
            e.currentTarget.style.boxShadow = `0 0 14px ${color}44`;
          }
        }}
        onMouseLeave={e => {
          if (!disabled) {
            e.currentTarget.style.background = 'rgba(0, 212, 255, 0.09)';
            e.currentTarget.style.boxShadow = `0 0 8px ${color}1a`;
          }
        }}
      >
        <IconComponent size={12} />
        EXECUTE
      </button>
    </div>
  );
}
