import React, { useRef, useState, useCallback } from 'react';

/* Knob sweeps 270°: from -135° (7 o'clock) to +135° (5 o'clock) */
const MIN_A = -135;
const MAX_A =  135;

function v2a(value, min, max) {
  const pct = Math.max(0, Math.min(1, (value - min) / (max - min)));
  return MIN_A + pct * (MAX_A - MIN_A);
}
function a2v(angle, min, max) {
  const pct = (angle - MIN_A) / (MAX_A - MIN_A);
  return min + pct * (max - min);
}
function toXY(cx, cy, r, deg) {
  const rad = ((deg - 90) * Math.PI) / 180;
  return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
}

export default function ControlKnob({
  label, value, min, max, unit, disabled, color = '#00d4ff', onChange,
}) {
  const svgRef   = useRef(null);
  const dragRef  = useRef(null);
  const [angle, setAngle] = useState(() => v2a(value ?? min, min, max));
  const [dragging, setDragging] = useState(false);

  const clampAngle = a => Math.max(MIN_A, Math.min(MAX_A, a));

  const angleFromEvent = useCallback((e, cx, cy) => {
    const px = e.touches?.[0]?.clientX ?? e.clientX;
    const py = e.touches?.[0]?.clientY ?? e.clientY;
    let deg = (Math.atan2(py - cy, px - cx) * 180) / Math.PI + 90;
    if (deg > 180) deg -= 360;
    return clampAngle(deg);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const handleMouseDown = useCallback(e => {
    if (disabled) return;
    e.preventDefault();
    const rect = svgRef.current.getBoundingClientRect();
    const cx = rect.left + rect.width  / 2;
    const cy = rect.top  + rect.height / 2;
    dragRef.current = { cx, cy };
    setDragging(true);

    const onMove = ev => {
      const a = angleFromEvent(ev, cx, cy);
      setAngle(a);
    };
    const onUp = ev => {
      const a = angleFromEvent(ev, cx, cy);
      setAngle(a);
      onChange && onChange(Math.round(a2v(a, min, max)));
      setDragging(false);
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup',   onUp);
    };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup',   onUp);
  }, [disabled, angleFromEvent, min, max, onChange]);

  const currentValue = Math.round(a2v(angle, min, max));

  /* SVG geometry */
  const CX = 44, CY = 44, R = 34;
  const startP = toXY(CX, CY, R, MIN_A);
  const valueP = toXY(CX, CY, R, angle);
  const endP   = toXY(CX, CY, R, MAX_A);
  const sweep  = angle - MIN_A;         // degrees filled
  const largeArc = sweep > 180 ? 1 : 0;
  const trackLarge = 1;                 // always large

  const handleKeyDown = e => {
    if (disabled) return;
    const step = 5;
    if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
      e.preventDefault();
      const next = Math.min(max, currentValue + step);
      setAngle(v2a(next, min, max));
      onChange && onChange(next);
    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
      e.preventDefault();
      const next = Math.max(min, currentValue - step);
      setAngle(v2a(next, min, max));
      onChange && onChange(next);
    }
  };

  return (
    <div
      style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '6px', userSelect: 'none' }}
      tabIndex={disabled ? -1 : 0}
      role="slider"
      aria-label={label}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuenow={currentValue}
      onKeyDown={handleKeyDown}
    >
      {/* Label */}
      <div style={{
        fontFamily:    "'Share Tech Mono', monospace",
        fontSize:      '9px',
        color:         'var(--text-muted)',
        letterSpacing: '0.08em',
        textTransform: 'uppercase',
        textAlign:     'center',
        maxWidth:      '88px',
        lineHeight:    1.3,
      }}>
        {label}
      </div>

      {/* SVG knob */}
      <svg
        ref={svgRef}
        width="88" height="88" viewBox="0 0 88 88"
        onMouseDown={handleMouseDown}
        style={{
          cursor:  disabled ? 'not-allowed' : dragging ? 'grabbing' : 'grab',
          opacity: disabled ? 0.4 : 1,
          filter:  dragging ? `drop-shadow(0 0 8px ${color}70)` : 'none',
          transition: 'filter 200ms, opacity 200ms',
        }}
      >
        {/* Outer ring */}
        <circle cx={CX} cy={CY} r={R + 6}
          fill="rgba(0, 8, 25, 0.85)"
          stroke={`${color}18`}
          strokeWidth="1"
        />

        {/* Full track (270°) */}
        <path
          d={`M ${startP.x} ${startP.y} A ${R} ${R} 0 ${trackLarge} 1 ${endP.x} ${endP.y}`}
          fill="none"
          stroke="rgba(0,212,255,0.09)"
          strokeWidth="6"
          strokeLinecap="round"
        />

        {/* Filled arc */}
        {sweep > 0.5 && (
          <path
            d={`M ${startP.x} ${startP.y} A ${R} ${R} 0 ${largeArc} 1 ${valueP.x} ${valueP.y}`}
            fill="none"
            stroke={color}
            strokeWidth="6"
            strokeLinecap="round"
            style={{ filter: `drop-shadow(0 0 4px ${color})` }}
          />
        )}

        {/* Centre cap */}
        <circle cx={CX} cy={CY} r="17"
          fill="rgba(0, 12, 34, 0.95)"
          stroke={`${color}28`}
          strokeWidth="1"
        />

        {/* Pointer line */}
        <line
          x1={CX} y1={CY}
          x2={valueP.x * 0.42 + CX * 0.58}
          y2={valueP.y * 0.42 + CY * 0.58}
          stroke={color}
          strokeWidth="2"
          strokeLinecap="round"
          style={{ filter: `drop-shadow(0 0 3px ${color})` }}
        />
      </svg>

      {/* Value readout */}
      <div style={{
        fontFamily:    "'Share Tech Mono', monospace",
        fontSize:      '18px',
        color,
        textShadow:    `0 0 10px ${color}55`,
        letterSpacing: '0.03em',
        lineHeight:    1,
      }}>
        {currentValue}
        <span style={{ fontSize: '11px', color: 'var(--text-muted)', marginLeft: '3px' }}>
          {unit}
        </span>
      </div>
    </div>
  );
}
