import React, { useState, useEffect } from 'react';
import { Wind } from 'lucide-react';

export default function ReducedMotionToggle() {
  const [reduced, setReduced] = useState(() =>
    typeof window !== 'undefined' && typeof window.matchMedia === 'function'
      ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
      : false
  );

  useEffect(() => {
    document.documentElement.dataset.reducedMotion = String(reduced);
  }, [reduced]);

  return (
    <button
      id="reduced-motion-toggle"
      onClick={() => setReduced(r => !r)}
      title={reduced ? 'Enable animations' : 'Disable animations'}
      style={{
        display:        'flex',
        alignItems:     'center',
        gap:            '5px',
        background:     'transparent',
        border:         `1px solid ${reduced ? 'var(--amber-dim, rgba(255,215,0,0.4))' : 'var(--border-glow)'}`,
        borderRadius:   'var(--radius-sm)',
        color:          reduced ? 'var(--amber)' : 'var(--text-muted)',
        padding:        '4px 9px',
        fontSize:       '10px',
        cursor:         'pointer',
        fontFamily:     "'Share Tech Mono', monospace",
        letterSpacing:  '0.06em',
        transition:     'color 200ms, border-color 200ms',
      }}
    >
      <Wind size={11} />
      {reduced ? 'MOTION OFF' : 'MOTION ON'}
    </button>
  );
}
