import { useState, useEffect, useCallback } from 'react';
import { fetchAudit } from '../api/gateway';

const DEFAULT_AUDIT = {
  'refinery-1': [
    { command: 'set_temperature', value: 340, actor: 'operator (sim)', requested_at: new Date(Date.now() - 12 * 60 * 1000).toISOString(), status: 'applied' },
    { command: 'heater_enable',   value: 1,   actor: 'system-init',    requested_at: new Date(Date.now() - 40 * 60 * 1000).toISOString(), status: 'applied' },
  ],
  'refinery-2': [
    { command: 'set_flow_rate',   value: 125, actor: 'operator (sim)', requested_at: new Date(Date.now() - 18 * 60 * 1000).toISOString(), status: 'applied' },
    { command: 'pump_enable',     value: 1,   actor: 'system-init',    requested_at: new Date(Date.now() - 45 * 60 * 1000).toISOString(), status: 'applied' },
  ],
};

export function useAudit(machineId) {
  const [entries, setEntries] = useState(() => DEFAULT_AUDIT[machineId] || []);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try {
      const data = await fetchAudit(machineId);
      const list = Array.isArray(data) ? data : data.entries || [];
      if (list.length > 0) {
        setEntries(list);
      }
    } catch (_) {
      // keep simulated baseline
    } finally {
      setLoading(false);
    }
  }, [machineId]);

  useEffect(() => {
    load();
    const id = setInterval(load, 5000);

    const handleLocalCommand = e => {
      const entry = e.detail;
      if (!machineId || entry.machineId === machineId) {
        setEntries(prev => [entry, ...prev]);
      }
    };
    window.addEventListener('scada-command-applied', handleLocalCommand);

    return () => {
      clearInterval(id);
      window.removeEventListener('scada-command-applied', handleLocalCommand);
    };
  }, [load, machineId]);

  return { entries, loading, refresh: load };
}
