import React, { useRef, useEffect } from 'react';

export default function TelemetryLabel({ label, value, unit, isOffline }) {
  const valRef  = useRef(null);
  const prevRef = useRef(value);

  useEffect(() => {
    if (prevRef.current !== value && valRef.current) {
      valRef.current.style.animation = 'none';
      // Trigger reflow to restart animation
      void valRef.current.offsetWidth;
      valRef.current.style.animation = 'value-flash 700ms ease-out forwards';
    }
    prevRef.current = value;
  }, [value]);

  const displayVal = value !== null && value !== undefined
    ? (typeof value === 'number' ? value.toFixed(1) : value)
    : '—';

  return (
    <div style={{
      display:       'flex',
      flexDirection: 'column',
      alignItems:    'center',
      gap:           '2px',
    }}>
      <span style={{
        fontFamily:    "'Share Tech Mono', monospace",
        fontSize:      '9px',
        color:         'var(--text-muted)',
        letterSpacing: '0.1em',
        textTransform: 'uppercase',
      }}>
        {label}
      </span>

      <div style={{ display: 'flex', alignItems: 'baseline', gap: '3px' }}>
        <span
          ref={valRef}
          style={{
            fontFamily:  "'Share Tech Mono', monospace",
            fontSize:    '20px',
            fontWeight:  'bold',
            color:       isOffline ? 'var(--text-muted)' : 'var(--cyan)',
            textShadow:  isOffline ? 'none' : '0 0 10px rgba(0,212,255,0.5)',
            transition:  'color 400ms',
          }}
        >
          {displayVal}
        </span>
        {unit && (
          <span style={{
            fontFamily: "'Share Tech Mono', monospace",
            fontSize:   '11px',
            color:      'var(--text-muted)',
          }}>
            {unit}
          </span>
        )}
      </div>
    </div>
  );
}
