import React, { useRef, useEffect, useCallback } from 'react';
import MachineNode from './MachineNode';

/* ── Particle system ─────────────────────────────────────────────────────── */
function makeParticles(w, h, n = 40) {
  return Array.from({ length: n }, () => ({
    x:  Math.random() * w,
    y:  Math.random() * h,
    vx: (Math.random() - 0.5) * 0.2,
    vy: (Math.random() - 0.5) * 0.2,
    r:  Math.random() * 1.2 + 0.3,
    a:  Math.random() * 0.3 + 0.05,
  }));
}

/* ── Thick animated connection pipe SVG ────────────────────────────────────── */
function ThickPipe({ r1Online, r2Online, isOffline }) {
  const active   = r1Online && r2Online && !isOffline;
  const primary  = active ? '#00d4ff' : '#22384d';
  const energy   = active ? '#00d4ff' : '#142533';
  const glowCore = active ? 'rgba(0, 212, 255, 0.95)' : 'transparent';
  const neonGlow = active ? 'rgba(0, 212, 255, 0.85)' : 'transparent';

  return (
    <svg
      viewBox="0 0 1000 600"
      preserveAspectRatio="none"
      style={{
        position:      'absolute',
        top:           0,
        left:          0,
        width:         '100%',
        height:        '100%',
        pointerEvents: 'none',
        zIndex:        6,
        overflow:      'visible',
      }}
    >
      <defs>
        {/* Intense multi-stage glow filters */}
        <filter id="neon-glow" x="-30%" y="-30%" width="160%" height="160%">
          <feGaussianBlur stdDeviation="8" result="blur1" />
          <feGaussianBlur stdDeviation="16" result="blur2" />
          <feMerge>
            <feMergeNode in="blur2" />
            <feMergeNode in="blur1" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>

        <filter id="core-glow" x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur stdDeviation="4" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>

        {/* Conduit metallic exterior gradient */}
        <linearGradient id="conduit-grad" x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%"   stopColor={primary} stopOpacity="0.95" />
          <stop offset="50%"  stopColor={active ? '#66e8ff' : '#2d4a66'} stopOpacity="1" />
          <stop offset="100%" stopColor={primary} stopOpacity="0.95" />
        </linearGradient>

        {/* Conduit cylindrical depth gradient */}
        <linearGradient id="conduit-sheen" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%"   stopColor="rgba(255, 255, 255, 0.4)" />
          <stop offset="25%"  stopColor="rgba(0, 212, 255, 0.2)" />
          <stop offset="50%"  stopColor="rgba(0, 10, 26, 0.95)" />
          <stop offset="85%"  stopColor="rgba(0, 212, 255, 0.2)" />
          <stop offset="100%" stopColor="rgba(0, 0, 0, 0.85)" />
        </linearGradient>

        {/* Energy beam plasma gradient */}
        <linearGradient id="energy-beam-grad" x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%"   stopColor="#0099cc" />
          <stop offset="50%"  stopColor="#00d4ff" />
          <stop offset="100%" stopColor="#0099cc" />
        </linearGradient>
      </defs>

      {/* ── Outer Conduit Back-Shadow & Atmospheric Glow ────────── */}
      {active && (
        <rect
          x="376"
          y="278"
          width="248"
          height="44"
          rx="22"
          fill="none"
          stroke={primary}
          strokeWidth="12"
          opacity="0.4"
          filter="url(#neon-glow)"
        />
      )}

      {/* ── Main Outer Conduit (Thick casing 44px) ─────────────── */}
      <rect
        x="378"
        y="280"
        width="244"
        height="40"
        rx="20"
        fill="url(#conduit-sheen)"
        stroke={primary}
        strokeWidth="3"
        style={{
          filter: active ? `drop-shadow(0 0 14px ${glowCore})` : 'none',
        }}
      />

      {/* ── Interior Conduit Core Chamber ───────────────────────── */}
      <rect
        x="380"
        y="286"
        width="240"
        height="28"
        rx="14"
        fill="rgba(0, 10, 26, 0.92)"
      />

      {/* ── Structural Rib Segments / High-tech Rings ──────────── */}
      {[420, 460, 500, 540, 580].map(cx => (
        <g key={cx}>
          <line
            x1={cx} y1="280"
            x2={cx} y2="320"
            stroke={primary}
            strokeWidth="2.5"
            strokeOpacity={active ? 0.8 : 0.3}
          />
          {active && (
            <circle
              cx={cx} cy="300" r="2"
              fill="#ffffff"
              opacity="0.9"
              filter="url(#core-glow)"
            />
          )}
        </g>
      ))}

      {/* ── Broad Energy Glow Band inside pipe ─────────────────── */}
      {active && (
        <line
          x1="380" y1="300"
          x2="620" y2="300"
          stroke="url(#energy-beam-grad)"
          strokeWidth="16"
          strokeOpacity="0.5"
          filter="url(#core-glow)"
        />
      )}

      {/* ── Thick High-Intensity Core Laser Line ───────────────── */}
      <line
        x1="380" y1="300"
        x2="620" y2="300"
        stroke={energy}
        strokeWidth={active ? 6 : 2}
        strokeOpacity={active ? 0.95 : 0.4}
        style={{
          filter: active ? `drop-shadow(0 0 10px ${neonGlow})` : 'none',
        }}
      />

      {/* ── Animated Fast Moving Energy Pulses ─────────────────── */}
      {active && (
        <>
          {/* Glowing pulse segment layer 1 (fast pulse) */}
          <line
            x1="380" y1="300"
            x2="620" y2="300"
            stroke="#ffffff"
            strokeWidth="4"
            strokeDasharray="24 36"
            strokeLinecap="round"
            style={{ filter: 'drop-shadow(0 0 8px #00d4ff)' }}
          >
            <animate
              attributeName="stroke-dashoffset"
              from="120"
              to="0"
              dur="0.8s"
              repeatCount="indefinite"
            />
          </line>

          {/* Glowing pulse segment layer 2 (longer secondary wave) */}
          <line
            x1="380" y1="300"
            x2="620" y2="300"
            stroke="#80eaff"
            strokeWidth="3"
            strokeDasharray="40 60"
            strokeLinecap="round"
            opacity="0.9"
          >
            <animate
              attributeName="stroke-dashoffset"
              from="200"
              to="0"
              dur="1.4s"
              repeatCount="indefinite"
            />
          </line>

          {/* Traveling energy capsules / photon bullets */}
          <circle cx="0" cy="300" r="5" fill="#ffffff" filter="url(#core-glow)">
            <animate
              attributeName="cx"
              values="385; 615"
              dur="1.1s"
              repeatCount="indefinite"
            />
          </circle>
          <circle cx="0" cy="300" r="4" fill="#00d4ff" filter="url(#neon-glow)">
            <animate
              attributeName="cx"
              values="385; 615"
              dur="1.1s"
              begin="0.55s"
              repeatCount="indefinite"
            />
          </circle>
        </>
      )}

      {/* ── Animated Direction Chevrons Inside Conduit ─────────── */}
      {active && (
        <g opacity="0.95">
          {[415, 455, 495, 535, 575].map(x => (
            <path
              key={x}
              d={`M ${x - 5} 294 L ${x + 3} 300 L ${x - 5} 306`}
              fill="none"
              stroke="#00d4ff"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeLinejoin="round"
              style={{ filter: 'drop-shadow(0 0 5px #00d4ff)' }}
            >
              <animate
                attributeName="opacity"
                values="0.3;1;0.3"
                dur="1s"
                begin={`${(x - 415) * 0.003}s`}
                repeatCount="indefinite"
              />
            </path>
          ))}
        </g>
      )}

      {/* ── Heavy Industrial Coupling Flanges (Left & Right) ─────── */}
      {/* Left Flange (R1 Heater anchor) */}
      <rect
        x="368"
        y="266"
        width="12"
        height="68"
        rx="5"
        fill="url(#conduit-grad)"
        stroke={primary}
        strokeWidth="2"
        style={{ filter: active ? `drop-shadow(0 0 10px ${glowCore})` : 'none' }}
      />
      <rect
        x="376"
        y="272"
        width="6"
        height="56"
        rx="3"
        fill={active ? '#00d4ff' : '#22384d'}
        opacity="0.85"
      />

      {/* Right Flange (R2 Flow Unit anchor) */}
      <rect
        x="620"
        y="266"
        width="12"
        height="68"
        rx="5"
        fill="url(#conduit-grad)"
        stroke={primary}
        strokeWidth="2"
        style={{ filter: active ? `drop-shadow(0 0 10px ${glowCore})` : 'none' }}
      />
      <rect
        x="618"
        y="272"
        width="6"
        height="56"
        rx="3"
        fill={active ? '#00d4ff' : '#22384d'}
        opacity="0.85"
      />

      {/* ── Central Holographic Transfer HUD Badge ─────────────── */}
      <g transform="translate(500, 240)">
        {/* HUD pill background */}
        <rect
          x="-95"
          y="-13"
          width="190"
          height="26"
          rx="13"
          fill="rgba(0, 10, 28, 0.95)"
          stroke={active ? 'rgba(0, 212, 255, 0.5)' : 'rgba(120, 168, 204, 0.2)'}
          strokeWidth="1.5"
          style={{ filter: active ? 'drop-shadow(0 0 10px rgba(0, 212, 255, 0.35))' : 'none' }}
        />

        {/* Live indicator dot */}
        <circle
          cx="-76"
          cy="0"
          r="4"
          fill={active ? '#00d4ff' : '#ff3366'}
          style={{ filter: active ? 'drop-shadow(0 0 6px #00d4ff)' : 'none' }}
        >
          {active && (
            <animate
              attributeName="opacity"
              values="1;0.4;1"
              dur="1.2s"
              repeatCount="indefinite"
            />
          )}
        </circle>

        {/* HUD Text label */}
        <text
          x="-64"
          y="4"
          fill={active ? '#00d4ff' : '#78a8cc'}
          style={{
            fontFamily: "'Share Tech Mono', monospace",
            fontSize: '11px',
            fontWeight: 'bold',
            letterSpacing: '0.12em',
          }}
        >
          {active ? 'INTERCONNECT FLOW' : 'CONDUIT OFFLINE'}
        </text>

        {/* Direction arrow badge */}
        {active && (
          <path
            d="M 68 -4 L 75 0 L 68 4"
            fill="none"
            stroke="#00d4ff"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <animate
              attributeName="transform"
              type="translate"
              values="0,0; 4,0; 0,0"
              dur="1s"
              repeatCount="indefinite"
            />
          </path>
        )}
      </g>
    </svg>
  );
}

export default function HologramScene({
  telemetry, selectedMachine, onSelectMachine, isOffline, isDemoMode, alarms,
}) {
  const canvasRef = useRef(null);
  const animRef   = useRef(null);
  const partRef   = useRef([]);

  const activeAlarmIds = new Set(
    (alarms || []).filter(a => a.status !== 'acknowledged').map(a => a.machine_id)
  );

  const r1Online = !isOffline && telemetry?.refinery_1?.status !== 'offline';
  const r2Online = !isOffline && telemetry?.refinery_2?.status !== 'offline';

  /* ── Canvas particles ──────────────────────────────────────────────────── */
  const animate = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const { width: W, height: H } = canvas;
    ctx.clearRect(0, 0, W, H);

    const ps = partRef.current;
    ps.forEach(p => {
      p.x = (p.x + p.vx + W) % W;
      p.y = (p.y + p.vy + H) % H;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(0,212,255,${p.a})`;
      ctx.fill();
    });
    for (let i = 0; i < ps.length; i++) {
      for (let j = i + 1; j < ps.length; j++) {
        const dx = ps[i].x - ps[j].x;
        const dy = ps[i].y - ps[j].y;
        const d = Math.hypot(dx, dy);
        if (d < 100) {
          ctx.beginPath();
          ctx.moveTo(ps[i].x, ps[i].y);
          ctx.lineTo(ps[j].x, ps[j].y);
          ctx.strokeStyle = `rgba(0,212,255,${0.06 * (1 - d / 100)})`;
          ctx.lineWidth = 0.5;
          ctx.stroke();
        }
      }
    }
    animRef.current = requestAnimationFrame(animate);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ro = new ResizeObserver(() => {
      canvas.width = canvas.offsetWidth;
      canvas.height = canvas.offsetHeight;
      partRef.current = makeParticles(canvas.width, canvas.height);
    });
    ro.observe(canvas);
    canvas.width = canvas.offsetWidth;
    canvas.height = canvas.offsetHeight;
    partRef.current = makeParticles(canvas.width, canvas.height);
    animRef.current = requestAnimationFrame(animate);
    return () => { ro.disconnect(); if (animRef.current) cancelAnimationFrame(animRef.current); };
  }, [animate]);

  return (
    <div style={{
      position:   'relative',
      width:      '100%',
      height:     '100%',
      overflow:   'hidden',
      background: '#010a14',
      display:    'flex',
      alignItems: 'center',
    }}>
      {/* Particle canvas */}
      <canvas ref={canvasRef} style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', pointerEvents: 'none', zIndex: 1 }} />

      {/* Vignette overlay */}
      <div style={{
        position:      'absolute',
        inset:         0,
        background:    'radial-gradient(ellipse 80% 70% at 50% 50%, transparent 30%, rgba(1,10,20,0.65) 100%)',
        pointerEvents: 'none',
        zIndex:        2,
      }} />

      {/* Scanlines */}
      <div style={{
        position:      'absolute',
        inset:         0,
        background:    'repeating-linear-gradient(0deg, transparent, transparent 3px, rgba(0,212,255,0.008) 3px, rgba(0,212,255,0.008) 4px)',
        pointerEvents: 'none',
        zIndex:        3,
      }} />

      {/* ── Thick pipe SVG ── centred in the gap ─────────────── */}
      <ThickPipe r1Online={r1Online} r2Online={r2Online} isOffline={isOffline} />

      {/* ── Machine panels side by side ──────────────────────── */}
      <div style={{
        position:       'relative',
        zIndex:         10,
        display:        'flex',
        width:          '100%',
        height:         '100%',
        alignItems:     'stretch',
      }}>
        {/* Left machine — R1 */}
        <MachineNode
          machineId="refinery-1"
          telemetry={telemetry}
          isSelected={selectedMachine === 'refinery-1'}
          isOffline={isOffline}
          hasAlarm={activeAlarmIds.has('refinery-1')}
          alarmSeverity={(alarms || []).find(a => a.machine_id === 'refinery-1' && a.status !== 'acknowledged')?.severity || 'warning'}
          onClick={() => onSelectMachine(selectedMachine === 'refinery-1' ? null : 'refinery-1')}
        />

        {/* Centre gap for the pipe */}
        <div style={{ width: '24%', flexShrink: 0 }} />

        {/* Right machine — R2 */}
        <MachineNode
          machineId="refinery-2"
          telemetry={telemetry}
          isSelected={selectedMachine === 'refinery-2'}
          isOffline={isOffline}
          hasAlarm={activeAlarmIds.has('refinery-2')}
          alarmSeverity={(alarms || []).find(a => a.machine_id === 'refinery-2' && a.status !== 'acknowledged')?.severity || 'warning'}
          onClick={() => onSelectMachine(selectedMachine === 'refinery-2' ? null : 'refinery-2')}
        />
      </div>

      {/* ── Hint text ── */}
      {!selectedMachine && (
        <div style={{
          position:      'absolute',
          bottom:        '52px',
          left:          '50%',
          transform:     'translateX(-50%)',
          fontFamily:    "'Share Tech Mono', monospace",
          fontSize:      '11px',
          color:         'rgba(0,212,255,0.3)',
          letterSpacing: '0.18em',
          zIndex:        20,
          pointerEvents: 'none',
          whiteSpace:    'nowrap',
        }}>
          CLICK A MACHINE TO VIEW DETAILS
        </div>
      )}

      {/* ── Utility rail ── */}
      <div style={{
        position:      'absolute',
        bottom:        0, left: 0, right: 0,
        height:        '40px',
        background:    'rgba(0, 5, 15, 0.9)',
        borderTop:     '1px solid rgba(0,212,255,0.08)',
        backdropFilter: 'blur(10px)',
        display:       'flex',
        alignItems:    'center',
        padding:       '0 20px',
        gap:           '20px',
        zIndex:        20,
      }}>
        <span style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: '10px', letterSpacing: '0.12em', color: 'var(--text-muted)', borderRight: '1px solid rgba(0,212,255,0.1)', paddingRight: '16px' }}>
          UTILITY RAIL
        </span>
        <div style={{ display: 'flex', gap: '18px', fontFamily: "'Share Tech Mono', monospace", fontSize: '11px' }}>
          <span style={{ color: isOffline ? 'var(--danger)' : 'var(--cyan)' }}>
            GW: {isOffline ? 'OFFLINE' : 'ONLINE'}
            {isDemoMode && <span style={{ color: 'var(--amber)', marginLeft: '6px', fontSize: '9px' }}>[DEMO]</span>}
          </span>
          <span style={{ color: 'var(--text-muted)' }}>|</span>
          <span style={{ color: r1Online ? 'var(--cyan)' : 'var(--danger)' }}>R1: {r1Online ? 'NOMINAL' : 'FAULT'}</span>
          <span style={{ color: 'var(--text-muted)' }}>|</span>
          <span style={{ color: r2Online ? 'var(--cyan)' : 'var(--danger)' }}>R2: {r2Online ? 'NOMINAL' : 'FAULT'}</span>
        </div>
        <div style={{ marginLeft: 'auto', fontFamily: "'Share Tech Mono', monospace", fontSize: '10px', color: 'var(--text-muted)' }}>
          <LiveClock />
        </div>
      </div>
    </div>
  );
}

function LiveClock() {
  const [time, setTime] = React.useState(() => new Date());
  React.useEffect(() => {
    const id = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(id);
  }, []);
  return <>{time.toLocaleTimeString('en-US', { hour12: false })}</>;
}
