import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, AlertTriangle, Loader2 } from 'lucide-react';
import StatusBadge from '../shared/StatusBadge';

export default function CommandConfirmDialog({
  open, onClose, onConfirm,
  commandStatus, commandError,
  machineId, command, value, unit,
}) {
  const [reason, setReason] = useState('');

  const isSettled = ['applied', 'rejected', 'error'].includes(commandStatus);
  const isPending = commandStatus === 'pending';

  const handleConfirm = () => {
    onConfirm(reason || 'Operator adjustment');
  };

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          key="backdrop"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          style={{
            position:        'fixed',
            inset:           0,
            background:      'rgba(0, 4, 14, 0.88)',
            backdropFilter:  'blur(5px)',
            display:         'flex',
            alignItems:      'center',
            justifyContent:  'center',
            zIndex:          1000,
            padding:         '20px',
          }}
          onClick={e => { if (e.target === e.currentTarget && isSettled) { onClose(); setReason(''); } }}
        >
          <motion.div
            key="dialog"
            initial={{ scale: 0.88, opacity: 0, y: 24 }}
            animate={{ scale: 1,    opacity: 1, y: 0  }}
            exit={{    scale: 0.88, opacity: 0, y: 24 }}
            transition={{ type: 'spring', damping: 22, stiffness: 280 }}
            style={{
              background:   'rgba(0, 12, 32, 0.99)',
              border:       '1px solid rgba(0, 212, 255, 0.28)',
              borderRadius: '14px',
              padding:      '24px',
              width:        '100%',
              maxWidth:     '420px',
              boxShadow:    '0 0 50px rgba(0, 212, 255, 0.08), 0 24px 64px rgba(0,0,0,0.85)',
            }}
          >
            {/* ── Header ─────────────────────────────────────────── */}
            <div style={{
              display:        'flex',
              alignItems:     'center',
              justifyContent: 'space-between',
              marginBottom:   '20px',
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                <AlertTriangle size={17} color="var(--amber)" />
                <span style={{
                  fontFamily:    "'Rajdhani', sans-serif",
                  fontWeight:    700,
                  fontSize:      '16px',
                  letterSpacing: '0.14em',
                  color:         'var(--cyan)',
                }}>
                  CONFIRM COMMAND
                </span>
              </div>
              {(isSettled || !commandStatus) && (
                <button
                  id="dialog-close"
                  onClick={() => { onClose(); setReason(''); }}
                  style={{
                    background:   'transparent',
                    border:       '1px solid rgba(120,168,204,0.18)',
                    borderRadius: '6px',
                    color:        'var(--text-muted)',
                    cursor:       'pointer',
                    padding:      '5px',
                    display:      'flex',
                    alignItems:   'center',
                  }}
                >
                  <X size={14} />
                </button>
              )}
            </div>

            {/* ── Command summary ─────────────────────────────────── */}
            <div style={{
              padding:      '14px',
              background:   'rgba(0, 212, 255, 0.04)',
              border:       '1px solid rgba(0, 212, 255, 0.12)',
              borderRadius: '8px',
              marginBottom: '18px',
              fontFamily:   "'Share Tech Mono', monospace",
              fontSize:     '12px',
              lineHeight:   1.8,
            }}>
              <div>
                <span style={{ color: 'var(--text-muted)' }}>MACHINE: </span>
                <span style={{ color: 'var(--cyan)' }}>{(machineId || '').toUpperCase()}</span>
              </div>
              <div>
                <span style={{ color: 'var(--text-muted)' }}>COMMAND: </span>
                <span style={{ color: 'var(--amber)' }}>{(command || '').toUpperCase()}</span>
              </div>
              <div>
                <span style={{ color: 'var(--text-muted)' }}>VALUE: </span>
                <span style={{ color: 'var(--cyan)', fontSize: '18px', fontWeight: 'bold' }}>{value}</span>
                {unit && <span style={{ color: 'var(--text-muted)', marginLeft: '5px' }}>{unit}</span>}
              </div>
            </div>

            {/* ── Status feedback ─────────────────────────────────── */}
            {commandStatus && (
              <div style={{ marginBottom: '18px', display: 'flex', alignItems: 'center', gap: '10px', flexWrap: 'wrap' }}>
                {isPending && <Loader2 size={14} style={{ animation: 'spin 1s linear infinite', color: 'var(--amber)' }} />}
                <StatusBadge status={commandStatus} />
                {isPending && (
                  <span style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: '11px', color: 'var(--text-muted)' }}>
                    Awaiting gateway confirmation…
                  </span>
                )}
                {commandStatus === 'applied' && (
                  <span style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: '11px', color: 'var(--cyan)' }}>
                    Command applied successfully.
                  </span>
                )}
                {(commandStatus === 'rejected' || commandStatus === 'error') && (
                  <span style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: '11px', color: 'var(--danger)' }}>
                    {commandError || 'Command was rejected.'}
                  </span>
                )}
              </div>
            )}

            {/* ── Reason input + buttons ──────────────────────────── */}
            {!commandStatus && (
              <>
                <div style={{ marginBottom: '18px' }}>
                  <label style={{
                    display:       'block',
                    fontFamily:    "'Share Tech Mono', monospace",
                    fontSize:      '10px',
                    color:         'var(--text-muted)',
                    letterSpacing: '0.08em',
                    marginBottom:  '7px',
                  }}>
                    REASON (OPTIONAL)
                  </label>
                  <textarea
                    id="command-reason"
                    value={reason}
                    onChange={e => setReason(e.target.value)}
                    rows={2}
                    placeholder="Describe why this command is being issued…"
                    style={{
                      width:        '100%',
                      background:   'rgba(0, 12, 36, 0.85)',
                      border:       '1px solid rgba(0,212,255,0.18)',
                      borderRadius: '6px',
                      color:        'var(--text-primary)',
                      fontFamily:   "'Share Tech Mono', monospace",
                      fontSize:     '11px',
                      padding:      '9px 11px',
                      resize:       'vertical',
                      outline:      'none',
                    }}
                  />
                </div>

                <div style={{ display: 'flex', gap: '10px' }}>
                  <button
                    id="command-confirm-btn"
                    onClick={handleConfirm}
                    style={{
                      flex:          1,
                      padding:       '13px',
                      background:    'rgba(0, 212, 255, 0.1)',
                      border:        '1px solid rgba(0, 212, 255, 0.5)',
                      borderRadius:  '8px',
                      color:         'var(--cyan)',
                      cursor:        'pointer',
                      fontFamily:    "'Rajdhani', sans-serif",
                      fontWeight:    700,
                      fontSize:      '15px',
                      letterSpacing: '0.12em',
                      transition:    'all 200ms',
                      boxShadow:     '0 0 10px rgba(0,212,255,0.1)',
                    }}
                  >
                    CONFIRM
                  </button>
                  <button
                    id="command-cancel-btn"
                    onClick={() => { onClose(); setReason(''); }}
                    style={{
                      flex:          1,
                      padding:       '13px',
                      background:    'transparent',
                      border:        '1px solid rgba(120,168,204,0.25)',
                      borderRadius:  '8px',
                      color:         'var(--text-muted)',
                      cursor:        'pointer',
                      fontFamily:    "'Rajdhani', sans-serif",
                      fontSize:      '15px',
                      letterSpacing: '0.1em',
                      transition:    'all 200ms',
                    }}
                  >
                    CANCEL
                  </button>
                </div>
              </>
            )}

            {/* ── Post-settle close button ─────────────────────────── */}
            {isSettled && (
              <button
                onClick={() => { onClose(); setReason(''); }}
                style={{
                  width:         '100%',
                  padding:       '12px',
                  background:    'transparent',
                  border:        '1px solid rgba(0,212,255,0.28)',
                  borderRadius:  '8px',
                  color:         'var(--cyan)',
                  cursor:        'pointer',
                  fontFamily:    "'Rajdhani', sans-serif",
                  fontSize:      '14px',
                  letterSpacing: '0.1em',
                  transition:    'all 200ms',
                }}
              >
                CLOSE
              </button>
            )}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
